export const agentMarkdownByPath: Readonly<Record<string, string>> = {
  "/": "# GoBrand Calendar\n\n> Headless month, week, and day calendars built on Temporal.\n\nCanonical: https://calendar.gobrand.app/\n\nCoding agents should read https://calendar.gobrand.app/llms.txt before making Calendar changes.\n\nInstall the Calendar Agent Skill with `npx skills add go-brand/calendar`.\n\nReact installation: `pnpm add @gobrand/react-calendar @js-temporal/polyfill`.\n\nHuman documentation: https://calendar.gobrand.app/docs.\n",
  "/docs": "# React Calendar\n\n> Month, week, and day calendars for React, built on Temporal.\n\nCanonical: https://calendar.gobrand.app/docs\n\nYou bring the markup and styles. Calendar handles the date, the view, navigation, the timezone, and where each event goes.\n\n```tsx\nimport type { Temporal } from '@js-temporal/polyfill'\nimport { useCreateCalendar } from '@gobrand/react-calendar'\n\ntype Booking = {\n  id: string\n  guest: string\n  date: Temporal.PlainDate\n}\n\nfunction BookingCalendar({ bookings }: { bookings: Booking[] }) {\n  const calendar = useCreateCalendar({\n    views: { month: true },\n    items: bookings,\n    getDate: booking => booking.date,\n  })\n\n  return calendar.activeView.weeks.map(week => (\n    <div key={week[0].id}>\n      {week.map(day => (\n        <div key={day.id}>\n          {day.date.day}: {day.items.map(booking => booking.guest).join(', ')}\n        </div>\n      ))}\n    </div>\n  ))\n}\n```\n\nOnly `month` is enabled, so `activeView` is a month. Add `week` or `day` when you need them.\n\n[Build your first calendar](/docs/first-calendar) or [see month, week, and day together](/docs/examples/multi-view).\n",
  "/docs/installation": "# Installation\n\n> Install GoBrand React Calendar.\n\nCanonical: https://calendar.gobrand.app/docs/installation\n\n```bash\npnpm add @gobrand/react-calendar @js-temporal/polyfill\n```\n\nIt includes the core package and its types, and works with React 18 and 19.\n\nImport `Temporal` from the polyfill:\n\n```typescript\nimport { Temporal } from '@js-temporal/polyfill';\n\nconst launch = Temporal.PlainDate.from('2026-07-10');\nconst standup = Temporal.ZonedDateTime.from('2026-07-10T09:00[Europe/Madrid]');\n```\n",
  "/docs/first-calendar": "# Your first calendar\n\n> Build a month calendar with navigation in one hook.\n\nCanonical: https://calendar.gobrand.app/docs/first-calendar\n\nTurn on a view, pass your events, and say which date each event is on.\n\n```tsx\nimport type { Temporal } from '@js-temporal/polyfill'\nimport { useCreateCalendar } from '@gobrand/react-calendar'\n\ntype Event = {\n  id: string\n  title: string\n  date: Temporal.PlainDate\n}\n\nfunction Calendar({ events }: { events: Event[] }) {\n  const calendar = useCreateCalendar({\n    views: { month: true },\n    items: events,\n    getDate: event => event.date,\n  })\n\n  return (\n    <section>\n      <button onClick={calendar.previous}>Previous</button>\n      <h2>{calendar.title()}</h2>\n      <button onClick={calendar.next}>Next</button>\n      {calendar.activeView.weeks.flat().map(day => (\n        <div key={day.id}>\n          {day.date.toString()}: {day.items.map(event => event.title).join(', ')}\n        </div>\n      ))}\n    </section>\n  )\n}\n```\n\nTypeScript infers `Event` from `items`, and `activeView` is a month because month is the only view.\n\n[Complete basic-month source](https://calendar.gobrand.app/examples/basic-month.md) (export `BasicMonthExample`).\n\nThe calendar keeps the date and view, moves with `previous()`, `next()`, and `today()`, gives you a localized `title()`, and builds the grid. Your app owns the markup, styles, and data fetching.\n\n## Events with a start time\n\nIf your events have a `Temporal.ZonedDateTime` start, give `getDate` the date part:\n\n```tsx\nconst calendar = useCreateCalendar({\n  views: { month: true, week: true, day: true },\n  timeZone: 'Europe/Madrid',\n  items: events,\n  getDate: event => event.startsAt.withTimeZone('Europe/Madrid').toPlainDate(),\n  getStart: event => event.startsAt.withTimeZone('Europe/Madrid'),\n})\n```\n\n`getStart` places events in the week and day time slots. Convert to the calendar's timezone first, so an event at 23:30 UTC lands on the right local day. More in [timezones](/docs/timezones-and-ranges).\n\n[See month, week, and day together](/docs/examples/multi-view).\n",
  "/docs/data-and-suspense": "# Data and Suspense\n\n> Keep calendar controls available while a view loads its events.\n\nCanonical: https://calendar.gobrand.app/docs/data-and-suspense\n\nCreate the calendar without events above the Suspense boundary. Fetch and project the events inside the view.\n\n```tsx\nimport { Suspense } from 'react'\nimport type { Temporal } from '@js-temporal/polyfill'\nimport { useSuspenseQuery } from '@tanstack/react-query'\nimport {\n  CalendarProvider,\n  useCalendar,\n  useCalendarView,\n  useCreateCalendar,\n} from '@gobrand/react-calendar'\n\ntype Event = {\n  id: string\n  title: string\n  date: Temporal.PlainDate\n}\n\ntype CalendarProps = {\n  loadEvents(\n    start: Temporal.ZonedDateTime,\n    end: Temporal.ZonedDateTime,\n  ): Promise<Event[]>\n}\n\nfunction Calendar({ loadEvents }: CalendarProps) {\n  const calendar = useCreateCalendar({ views: { month: true } })\n\n  return (\n    <CalendarProvider calendar={calendar}>\n      <Controls />\n      <Suspense fallback={<p>Loading events…</p>}>\n        <MonthView loadEvents={loadEvents} />\n      </Suspense>\n    </CalendarProvider>\n  )\n}\n\nfunction Controls() {\n  const calendar = useCalendar()\n\n  return (\n    <nav>\n      <button onClick={calendar.previous}>Previous</button>\n      <strong>{calendar.title()}</strong>\n      <button onClick={calendar.next}>Next</button>\n    </nav>\n  )\n}\n\nfunction MonthView({ loadEvents }: CalendarProps) {\n  const calendar = useCalendar()\n  const { start, end } = calendar.visibleRange\n  const { data: events } = useSuspenseQuery({\n    queryKey: ['events', start.toString(), end.toString()],\n    queryFn: () => loadEvents(start, end),\n  })\n\n  const month = useCalendarView({\n    view: 'month',\n    items: events,\n    getDate: event => event.date,\n  })\n\n  return month.weeks.map(week => (\n    <div key={week[0].id}>\n      {week.map(day => (\n        <div key={day.id}>\n          {day.date.toString()}: {day.items.map(event => event.title).join(', ')}\n        </div>\n      ))}\n    </div>\n  ))\n}\n```\n\n`Controls` does not unmount when `MonthView` suspends, so navigation remains available while events load.\nThe example assumes your app already has TanStack Query's `QueryClientProvider`.\n\n## Different data for each view\n\nEach `useCalendarView` call infers its own item type. A month view can use summaries while a timed week view uses full event records. The shared controller does not need to know either type.\n\n[Complete suspense-month source](https://calendar.gobrand.app/examples/suspense-month.md) (export `SuspenseMonthExample`).\n",
  "/docs/timezones-and-ranges": "# Timezones and visible ranges\n\n> Show the right day in every timezone and query exactly what is on screen.\n\nCanonical: https://calendar.gobrand.app/docs/timezones-and-ranges\n\nSet the timezone once:\n\n```tsx\nconst calendar = useCreateCalendar({\n  views: { month: true, week: true },\n  timeZone: 'America/New_York',\n})\n```\n\nIt decides the starting date, `today()`, `isToday`, and the visible range. Leave it out to use the device's timezone; set it when rendering on a server or showing someone else's calendar.\n\n## Query what is on screen\n\n`visibleRange` covers every date in the current view. Include `start`, exclude `end`:\n\n```ts\nconst { start, end } = calendar.visibleRange\n\nawait db.event.findMany({\n  where: {\n    startsAt: { gte: start.toInstant(), lt: end.toInstant() },\n  },\n})\n```\n\nBoth are local midnights, so a day that daylight saving makes 23 or 25 hours long is still exactly one day.\n\n## Put events on the right day\n\nThe calendar's timezone does not convert your events. Convert each one to that timezone, then read the date and start from the same value:\n\n```ts\nimport { Temporal } from '@js-temporal/polyfill';\n\nconst meeting = {\n  title: 'Sync with Tokyo',\n  start: Temporal.Instant.from('2026-07-10T23:30:00Z').toZonedDateTimeISO('Europe/Madrid'),\n};\nconst getDate = (event: typeof meeting) => event.start.toPlainDate();\nconst getStart = (event: typeof meeting) => event.start;\n// getDate(meeting).toString() === '2026-07-11'\n// getStart(meeting).hour === 1\n```\n\nIn UTC the meeting is on July 10. In a Madrid calendar it is on July 11 at 01:30, and that is where it shows up.\n",
  "/docs/controlled-state": "# Controlled state and routing\n\n> Keep the calendar's date and view in the URL or your own state.\n\nCanonical: https://calendar.gobrand.app/docs/controlled-state\n\nPass `date` and `view` to control them, like a React input. Use `defaultDate` and `defaultView` to set only the starting values.\n\n| State | Controlled | Starting value only |\n| --- | --- | --- |\n| Date | `date` / `onDateChange` | `defaultDate` |\n| View | `view` / `onViewChange` | `defaultView` |\n\n```tsx\nconst calendar = useCreateCalendar({\n  views: { month: true, week: true },\n  date: search.date,\n  view: search.view,\n  onDateChange: date => navigate({ search: previous => ({ ...previous, date }) }),\n  onViewChange: view => navigate({ search: previous => ({ ...previous, view }) }),\n})\n```\n\nThe calendar follows the props right away, so the browser's back and forward buttons just work.\n\n## Use the current calendar\n\n`useCreateCalendar` can return a new calendar object after a render, for example when the date, view, or timezone changes. Read it and its actions from the current render. To subscribe, depend on it:\n\n```tsx\nuseEffect(() => calendar.subscribe(() => {\n  console.log(calendar.date.toString());\n}), [calendar]);\n```\n",
  "/docs/api/use-create-calendar": "# useCreateCalendar\n\n> Create a calendar in a component, with or without its events.\n\nCanonical: https://calendar.gobrand.app/docs/api/use-create-calendar\n\n```tsx\nconst calendar = useCreateCalendar({\n  views: { month: true, week: true },\n  defaultDate: Temporal.PlainDate.from('2026-07-10'),\n  defaultView: 'month',\n  timeZone: 'America/Asuncion',\n  items: events,\n  getDate: event => event.date,\n})\n```\n\nWith `items`, the result also has `activeView`, the current month, week, or day with your events on it. Without `items`, pass the calendar to `CalendarProvider` and build views with [`useCalendarView`](/docs/api/use-calendar-view).\n\n| Option | |\n| --- | --- |\n| `views` | Required. `{ month: true }`, or `{ week: { dayStart, dayEnd, slotDuration } }` for custom hours. |\n| `defaultDate`, `defaultView` | Starting values. |\n| `date`, `onDateChange`, `view`, `onViewChange` | [Controlled state](/docs/controlled-state). |\n| `timeZone` | IANA name. Defaults to the device timezone. |\n| `weekStartsOn` | `1` (Monday) through `7` (Sunday). Defaults to the locale's first day. |\n| `items`, `getDate`, `getStart` | Your events and where each one goes. |\n\nUse the calendar from the current render; it can change between renders. When rendering on the server, pass the same `date`, `view`, and `timeZone` on the server and the client.\n",
  "/docs/api/use-calendar": "# useCalendar\n\n> Read the calendar from CalendarProvider.\n\nCanonical: https://calendar.gobrand.app/docs/api/use-calendar\n\n```tsx\nfunction Toolbar() {\n  const calendar = useCalendar()\n  return (\n    <button onClick={calendar.next}>{calendar.title()}</button>\n  )\n}\n```\n\nThe component re-renders when the date or view changes. Event types belong to [`useCalendarView`](/docs/api/use-calendar-view), so `useCalendar` takes none.\n\nYou can also pass a calendar made with core `createCalendar` to the provider. Create it once, for example in `useState`, not on every render.\n",
  "/docs/api/use-calendar-view": "# useCalendarView\n\n> Put events into one view of a shared calendar.\n\nCanonical: https://calendar.gobrand.app/docs/api/use-calendar-view\n\n`useCalendarView` reads the calendar from `CalendarProvider`, or from a `calendar` you pass. TypeScript infers the event type from `items`.\n\n```tsx\nimport type { Temporal } from '@js-temporal/polyfill'\nimport { useCalendarView } from '@gobrand/react-calendar'\n\ntype Meeting = {\n  id: string\n  title: string\n  startsAt: Temporal.ZonedDateTime\n}\n\nfunction WeekContent({ meetings }: { meetings: Meeting[] }) {\n  const week = useCalendarView({\n    view: 'week',\n    items: meetings,\n    getDate: meeting => meeting.startsAt.toPlainDate(),\n    getStart: meeting => meeting.startsAt,\n  })\n\n  return week.days.map(day => (\n    <div key={day.id}>\n      {day.date.toString()}: {day.items.map(meeting => meeting.title).join(', ')}\n    </div>\n  ))\n}\n```\n\n`getDate` is required with `items`. Add `getStart` to place events in time slots. The view you ask for is the view you get: `view: 'week'` stays a week even when the calendar switches to month.\n",
  "/docs/api/calendar-provider": "# CalendarProvider\n\n> Share one calendar with the components below it.\n\nCanonical: https://calendar.gobrand.app/docs/api/calendar-provider\n\n```tsx\nimport {\n  CalendarProvider,\n  useCalendar,\n  useCreateCalendar,\n} from '@gobrand/react-calendar'\n\nfunction Calendar() {\n  const calendar = useCreateCalendar({ views: { month: true } })\n\n  return (\n    <CalendarProvider calendar={calendar}>\n      <Controls />\n      <VisibleRange />\n    </CalendarProvider>\n  )\n}\n\nfunction Controls() {\n  const calendar = useCalendar()\n\n  return (\n    <nav>\n      <button onClick={calendar.previous}>Previous</button>\n      <strong>{calendar.title()}</strong>\n      <button onClick={calendar.next}>Next</button>\n    </nav>\n  )\n}\n\nfunction VisibleRange() {\n  const { visibleRange } = useCalendar()\n\n  return <p>{visibleRange.start.toString()} – {visibleRange.end.toString()}</p>\n}\n```\n\nThe provider shares the date and view, not events. Each view below it can load its own data.\n",
  "/docs/types": "# Types\n\n> The shapes you render, from the calendar to its days and time slots.\n\nCanonical: https://calendar.gobrand.app/docs/types\n\nAll types are exported from both `@gobrand/react-calendar` and `@gobrand/calendar-core`. `TItem` is your event type, inferred from `items`.\n\n```ts\nimport type { Temporal } from '@js-temporal/polyfill';\n\ntype VisibleRange = {\n  start: Temporal.ZonedDateTime; // included\n  end: Temporal.ZonedDateTime; // excluded\n};\n\ntype MonthView<TItem> = {\n  name: 'month';\n  month: Temporal.PlainYearMonth;\n  weeks: Array<\n    Array<{\n      id: string;\n      date: Temporal.PlainDate;\n      isCurrentMonth: boolean;\n      isToday: boolean;\n      items: TItem[];\n    }>\n  >;\n};\n\ntype TimeSlot<TItem> = {\n  id: string;\n  time: Temporal.PlainTime;\n  hour: number;\n  minute: number;\n  items: TItem[];\n};\n\ntype WeekView<TItem> = {\n  name: 'week';\n  weekStart: Temporal.PlainDate;\n  weekEnd: Temporal.PlainDate;\n  days: Array<{\n    id: string;\n    date: Temporal.PlainDate;\n    isToday: boolean;\n    items: TItem[];\n    timeSlots: TimeSlot<TItem>[];\n  }>;\n};\n\ntype DayView<TItem> = {\n  name: 'day';\n  id: string;\n  date: Temporal.PlainDate;\n  isToday: boolean;\n  items: TItem[];\n  timeSlots: TimeSlot<TItem>[];\n};\n```\n\nWith more than one view enabled, `activeView` is a union of those views. Check `activeView.name` to render the right one. Each view also has a `view` field with the same value; prefer `name`.\n\n`CalendarController` holds `date`, `view`, `viewNames`, `visibleRange`, `title()`, `next()`, `previous()`, `today()`, `setDate()`, `setView()`, and `subscribe()`.\n",
  "/docs/examples/basic-month": "# Month View\n\n> A month with navigation and events.\n\nCanonical: https://calendar.gobrand.app/docs/examples/basic-month\n\n[Complete basic-month source](https://calendar.gobrand.app/examples/basic-month.md) (export `BasicMonthExample`).\n\nMonth cells group events by date, so `getDate` is all it needs.\n\nThe styling comes from small `calendar-ui` components. [Full source as Markdown](/examples/basic-month.md).\n",
  "/docs/examples/date-picker": "# Date Picker\n\n> Pick a date from a month, with no event data.\n\nCanonical: https://calendar.gobrand.app/docs/examples/date-picker\n\n[Complete date-picker source](https://calendar.gobrand.app/examples/date-picker.md) (export `DatePickerExample`).\n\nNo `items` and no accessors: the month grid alone is enough to pick a date.\n\nThe styling comes from small `calendar-ui` components. [Full source as Markdown](/examples/date-picker.md).\n",
  "/docs/examples/week-view": "# Week View\n\n> A week of events, with or without time slots.\n\nCanonical: https://calendar.gobrand.app/docs/examples/week-view\n\n## Simple week\n\nEvents appear on each day.\n\n[Complete simple-week source](https://calendar.gobrand.app/examples/simple-week.md) (export `SimpleWeekExample`).\n\n## Week with time slots\n\nAdd `getStart` and timed events land in an hourly grid.\n\n[Complete week-slots source](https://calendar.gobrand.app/examples/week-slots.md) (export `WeekSlotsExample`).\n\nThe styling comes from small `calendar-ui` components. Full source as Markdown: [simple week](/examples/simple-week.md), [week with time slots](/examples/week-slots.md).\n",
  "/docs/examples/day-view": "# Day View\n\n> One day with hourly time slots.\n\nCanonical: https://calendar.gobrand.app/docs/examples/day-view\n\n[Complete day-view source](https://calendar.gobrand.app/examples/day-view.md) (export `DayViewExample`).\n\n`getStart` places each event in its time slot.\n\nThe styling comes from small `calendar-ui` components. [Full source as Markdown](/examples/day-view.md).\n",
  "/docs/examples/multi-view": "# Multi-View Calendar\n\n> One calendar that switches between month, week, and day.\n\nCanonical: https://calendar.gobrand.app/docs/examples/multi-view\n\n[Complete multi-view source](https://calendar.gobrand.app/examples/multi-view.md) (export `MultiViewExample`).\n\nFor events loaded from an API, see [Suspense Query](/docs/examples/suspense-query).\n\nThe styling comes from small `calendar-ui` components. [Full source as Markdown](/examples/multi-view.md).\n",
  "/docs/examples/suspense-query": "# Suspense Query\n\n> Keep month navigation usable while its events load.\n\nCanonical: https://calendar.gobrand.app/docs/examples/suspense-query\n\n[Complete suspense-month source](https://calendar.gobrand.app/examples/suspense-month.md) (export `SuspenseMonthExample`).\n\nThe toolbar sits above the Suspense boundary, so it stays usable while the month loads its events.\n\nThe styling comes from small `calendar-ui` components. [Full source as Markdown](/examples/suspense-month.md).\n",
  "/docs/core": "# Calendar Core\n\n> Month, week, and day calendars without a framework.\n\nCanonical: https://calendar.gobrand.app/docs/core\n\nCreate a calendar, then build the view you want to render from your own data.\n\n```ts\nimport { Temporal } from '@js-temporal/polyfill';\nimport { buildMonthView, createCalendar } from '@gobrand/calendar-core';\n\nconst bookings = [\n  { id: 'b1', guest: 'Ana', date: Temporal.PlainDate.from('2026-07-10') },\n  { id: 'b2', guest: 'Leo', date: Temporal.PlainDate.from('2026-07-24') },\n];\n\nconst calendar = createCalendar({\n  views: { month: true },\n  date: Temporal.PlainDate.from('2026-07-10'),\n  timeZone: 'Europe/Madrid',\n  weekStartsOn: 1,\n});\n\nconst month = buildMonthView({ calendar, items: bookings, getDate: (booking) => booking.date });\n\ncalendar.title('en-US'); // \"July 2026\"\nmonth.weeks.length; // 5\nmonth.weeks[1][4].items.map((booking) => booking.guest); // [\"Ana\"]\n```\n\nWithout `date` and `timeZone`, the calendar starts on today in the device's timezone.\n\nNext: [createCalendar](/docs/core/create-calendar), [view projections](/docs/core/projections), and [visible ranges](/docs/core/visible-ranges).\n",
  "/docs/core/installation": "# Installation\n\n> Install GoBrand Calendar Core.\n\nCanonical: https://calendar.gobrand.app/docs/core/installation\n\n```bash\npnpm add @gobrand/calendar-core @js-temporal/polyfill\n```\n\nTypes are included. Import `Temporal` from the polyfill and pass Temporal values to the calendar:\n\n```ts\nimport { Temporal } from '@js-temporal/polyfill';\n\nconst launch = Temporal.PlainDate.from('2026-07-10');\nconst standup = Temporal.ZonedDateTime.from('2026-07-10T09:00[Europe/Madrid]');\n```\n\nUsing React? Install [`@gobrand/react-calendar`](/docs/installation) instead; it includes the core package.\n",
  "/docs/core/create-calendar": "# createCalendar\n\n> Create a calendar with its date, view, timezone, and navigation.\n\nCanonical: https://calendar.gobrand.app/docs/core/create-calendar\n\n```ts\nimport { Temporal } from '@js-temporal/polyfill';\nimport { createCalendar } from '@gobrand/calendar-core';\n\nconst calendar = createCalendar({\n  views: {\n    month: true,\n    week: {\n      dayStart: Temporal.PlainTime.from('08:00'),\n      dayEnd: Temporal.PlainTime.from('18:00'),\n      slotDuration: Temporal.Duration.from({ minutes: 30 }),\n    },\n  },\n  date: Temporal.PlainDate.from('2026-07-10'),\n  timeZone: 'America/New_York',\n  weekStartsOn: 7,\n});\n\ncalendar.view; // \"month\"\ncalendar.next();\ncalendar.date.toString(); // \"2026-08-10\"\ncalendar.setView('week');\ncalendar.title('en-US'); // \"Aug 9 - Aug 15, 2026\"\n```\n\n| Option | Default |\n| --- | --- |\n| `views` | Required. Enable a view with `true`, or pass `dayStart`, `dayEnd`, and `slotDuration` for week and day. Leave a view out to disable it. |\n| `date` | Today in `timeZone`. A `Temporal.PlainDate`. |\n| `view` | The first view in `views`. |\n| `timeZone` | The device timezone. An IANA name such as `'Europe/Madrid'`. |\n| `weekStartsOn` | The locale's first day. `1` is Monday through `7` is Sunday. |\n\nThe calendar has `date`, `view`, `visibleRange`, `title()`, `next()`, `previous()`, `today()`, `setDate()`, `setView()`, and `subscribe()`.\n\nInputs of the wrong type throw a `TypeError` that names what you passed, for example `date must be a Temporal.PlainDate, got String`.\n",
  "/docs/core/projections": "# View Projections\n\n> Turn the calendar and your data into month, week, or day views.\n\nCanonical: https://calendar.gobrand.app/docs/core/projections\n\n`buildMonthView`, `buildWeekView`, and `buildDayView` place your items on dates. Each call takes its own items, so a month of booking counts and a week of full meetings can share one calendar.\n\n```ts\nimport { Temporal } from '@js-temporal/polyfill';\nimport { buildWeekView, createCalendar } from '@gobrand/calendar-core';\n\nconst meetings = [\n  {\n    title: 'Design review',\n    start: Temporal.ZonedDateTime.from('2026-07-08T10:30[Europe/Madrid]'),\n  },\n];\n\nconst calendar = createCalendar({\n  views: { week: true },\n  date: Temporal.PlainDate.from('2026-07-08'),\n  timeZone: 'Europe/Madrid',\n  weekStartsOn: 1,\n});\n\nconst week = buildWeekView({\n  calendar,\n  items: meetings,\n  getDate: (meeting) => meeting.start.toPlainDate(),\n  getStart: (meeting) => meeting.start,\n});\n\nweek.weekStart.toString(); // \"2026-07-06\"\nweek.days[2].items.length; // 1\nweek.days[2].timeSlots[10].items[0].title; // \"Design review\"\n```\n\n- `getDate` returns the `Temporal.PlainDate` an item belongs to. It is required when you pass `items`.\n- `getStart` returns a `Temporal.ZonedDateTime` and places the item in a time slot. Add it for week and day views with timed events.\n- Without `items`, you get the empty grid, which is all a date picker needs.\n\nThe calendar's timezone does not convert your items. Convert each event to that timezone first, then derive both accessors from it; see [timezones](/docs/timezones-and-ranges).\n",
  "/docs/core/visible-ranges": "# Visible ranges\n\n> The start and end to query for the dates on screen.\n\nCanonical: https://calendar.gobrand.app/docs/core/visible-ranges\n\n`visibleRange` covers every date the current view shows, including the leading and trailing days of a month grid.\n\n```ts\nimport { Temporal } from '@js-temporal/polyfill';\nimport { createCalendar } from '@gobrand/calendar-core';\n\nconst calendar = createCalendar({\n  views: { month: true },\n  date: Temporal.PlainDate.from('2026-03-15'),\n  timeZone: 'America/New_York',\n  weekStartsOn: 7,\n});\n\nconst { start, end } = calendar.visibleRange;\nstart.toString(); // \"2026-03-01T00:00:00-05:00[America/New_York]\"\nend.toString(); // \"2026-04-05T00:00:00-04:00[America/New_York]\"\n```\n\nInclude `start` and exclude `end`:\n\n```sql\nWHERE starts_at >= :start AND starts_at < :end\n```\n\nBoth are local midnights in the calendar's timezone, so a day that daylight saving makes 23 or 25 hours long is still one day. Use `.toInstant()` when your database stores UTC.\n",
  "/docs/core/utilities": "# Utilities\n\n> Weekday labels for calendar headers, and the Temporal one-liners for everything else.\n\nCanonical: https://calendar.gobrand.app/docs/core/utilities\n\n## getWeekdays\n\nWeekday names in the order your calendar shows them. `1` starts on Monday, `7` on Sunday.\n\n```ts\nimport { getWeekdays } from '@gobrand/calendar-core';\n\ngetWeekdays(); // [\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\", \"Sun\"]\ngetWeekdays(7); // [\"Sun\", \"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\"]\ngetWeekdays(1, 'es-ES', 'long'); // [\"lunes\", \"martes\", \"miércoles\", \"jueves\", \"viernes\", \"sábado\", \"domingo\"]\ngetWeekdays(7, 'en-US', 'narrow'); // [\"S\", \"M\", \"T\", \"W\", \"T\", \"F\", \"S\"]\n```\n\nUse the calendar's `weekStartsOn` so the header matches the grid.\n\n## Everything else is Temporal\n\nCalendar has no other helpers. Temporal already does the rest in one line:\n\n| Task | Temporal |\n| --- | --- |\n| Month name | `month.toLocaleString('en-US', { month: 'long' })` |\n| Time label | `time.toLocaleString('en-GB', { hour: '2-digit', minute: '2-digit' })` |\n| Device timezone | `Temporal.Now.timeZoneId()` |\n| Show a meeting in another timezone | `meeting.withTimeZone('Asia/Tokyo')` |\n| Date and time to a meeting | `date.toZonedDateTime({ timeZone, plainTime: time })` |\n| Next month, last week | `date.add({ months: 1 })`, `date.subtract({ weeks: 1 })` |\n\nFor formatting and arithmetic with date-fns names, see [Tiempo](https://tiempo.gobrand.app).\n"
};
